def forward(groups):
    kvstart = int(groups[0])
    kvend = int(groups[2])
    length_actual = int(groups[4])
    return {'stored': [kvstart, kvend, length_actual], 'layout': [groups[1], groups[3], groups[5]]}

def inverse(record):
    kvstart, kvend, length_actual = record['stored']
    kvstart_display, kvend_display, length_max = record['layout']
    return f"kvstart = {kvstart}({kvstart_display}); kvend = {kvend}({kvend_display}); length = {length_actual}/{length_max}"
